#include <iostream>
using namespace std;

int main() {
    int n, sum = 0, fingers;
    cin >> n;

    for (int i = 0; i < n; ++i) {
        cin >> fingers;
        sum += fingers;
    }

    int answer = 0;
    for (int i = 1; i <= 5; ++i) {
        if ((sum + i) % (n + 1) != 1) {
            ++answer;
        }
    }

    cout << answer << '\n';
    return 0;
}

